import React, { useState } from 'react';

const QuanLyThongBaoCuDan = () => {
    // 3 mục: 'xem' (Xem thông báo), 'admin' (Gửi Admin), 'nhom' (Gửi nhóm chung)
    const [activeTab, setActiveTab] = useState('xem');

    return (
        <div style={styles.container}>
            <header style={styles.header}>
                <h2 style={styles.mainTitle}>🔔 Trung Tâm Thông Báo & Kết Nối</h2>
                <div style={styles.tabBar}>
                    <button 
                        onClick={() => setActiveTab('xem')} 
                        style={{...styles.tabBtn, backgroundColor: activeTab === 'xem' ? '#2e7d32' : '#eee', color: activeTab === 'xem' ? '#fff' : '#666'}}
                    >
                        📢 Xem thông báo
                    </button>
                    <button 
                        onClick={() => setActiveTab('admin')} 
                        style={{...styles.tabBtn, backgroundColor: activeTab === 'admin' ? '#1976d2' : '#eee', color: activeTab === 'admin' ? '#fff' : '#666'}}
                    >
                        👨‍💼 Gửi Admin
                    </button>
                    <button 
                        onClick={() => setActiveTab('nhom')} 
                        style={{...styles.tabBtn, backgroundColor: activeTab === 'nhom' ? '#ed6c02' : '#eee', color: activeTab === 'nhom' ? '#fff' : '#666'}}
                    >
                        👥 Nhóm chung
                    </button>
                </div>
            </header>

            <div style={styles.mainCard}>
                {/* 1. XEM THÔNG BÁO (Từ Ban Quản Lý) */}
                {activeTab === 'xem' && (
                    <div className="fade-in">
                        <h3 style={{color: '#2e7d32', marginBottom: '15px'}}>Thông báo từ tòa nhà</h3>
                        <div style={styles.newsItem}>
                            <div style={styles.postHeader}>
                                <span style={styles.badgeMoi}>MỚI</span>
                                <span style={styles.timeLabel}>17/04/2026</span>
                            </div>
                            <h4 style={{margin: '10px 0'}}>Thông báo bảo trì thang máy tòa A</h4>
                            <p style={styles.postContent}>Thang máy số 3 tòa A sẽ tạm dừng hoạt động để bảo trì định kỳ từ 14h-16h chiều nay...</p>
                            <button style={styles.btnDetail}>Xem chi tiết</button>
                        </div>
                    </div>
                )}

                {/* 2. GỬI ADMIN (Phản hồi/Yêu cầu hỗ trợ) */}
                {activeTab === 'admin' && (
                    <div className="fade-in">
                        <h3 style={{color: '#1976d2', marginBottom: '20px'}}>Gửi yêu cầu tới Ban Quản Lý</h3>
                        <input type="text" placeholder="Chủ đề phản hồi (VD: Báo hỏng, Vệ sinh...)" style={{...styles.input, borderColor: '#1976d2'}} />
                        <textarea placeholder="Nội dung chi tiết cư dân cần hỗ trợ..." style={styles.textarea} />
                        <button style={{...styles.submitBtn, backgroundColor: '#1976d2'}}>📩 Gửi phản hồi ngay</button>
                    </div>
                )}

                {/* 3. NHÓM CHUNG (Chia sẻ cộng đồng) */}
                {activeTab === 'nhom' && (
                    <div className="fade-in">
                        <h3 style={{color: '#ed6c02', marginBottom: '20px'}}>Chia sẻ với cộng đồng cư dân</h3>
                        <textarea 
                            placeholder="Nội dung chia sẻ (VD: Tìm đồ lạc, rủ mua chung...)" 
                            style={{...styles.textarea, borderColor: '#ed6c02'}}
                        />
                        <button style={{...styles.submitBtn, backgroundColor: '#ed6c02'}}>🚀 Đăng lên bảng tin chung</button>
                    </div>
                )}
            </div>
        </div>
    );
};

const styles = {
    container: { padding: '20px', width: '100%', maxWidth: '950px', margin: '0 auto' },
    header: { textAlign: 'center', marginBottom: '30px' },
    mainTitle: { fontSize: '24px', fontWeight: 'bold', color: '#333' },
    tabBar: { display: 'inline-flex', gap: '10px', backgroundColor: '#f5f5f5', padding: '6px', borderRadius: '14px', marginTop: '20px' },
    tabBtn: { padding: '12px 25px', border: 'none', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold', transition: '0.3s' },
    mainCard: { backgroundColor: '#fff', padding: '35px', borderRadius: '25px', boxShadow: '0 10px 40px rgba(0,0,0,0.06)', minHeight: '400px' },
    input: { width: '100%', padding: '15px', marginBottom: '15px', borderRadius: '12px', border: '1px solid #eee', backgroundColor: '#fafafa', boxSizing: 'border-box' },
    textarea: { width: '100%', padding: '15px', height: '160px', marginBottom: '20px', borderRadius: '12px', border: '1px solid #eee', backgroundColor: '#fafafa', resize: 'none', boxSizing: 'border-box' },
    submitBtn: { width: '100%', padding: '16px', color: '#fff', border: 'none', borderRadius: '12px', fontWeight: 'bold', fontSize: '16px', cursor: 'pointer' },
    newsItem: { border: '1px solid #f0f0f0', padding: '20px', borderRadius: '15px', marginBottom: '15px', backgroundColor: '#fff', borderLeft: '5px solid #2e7d32' },
    postHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
    badgeMoi: { backgroundColor: '#ff4d4f', color: '#fff', padding: '3px 8px', borderRadius: '5px', fontSize: '10px', fontWeight: 'bold' },
    timeLabel: { color: '#bbb', fontSize: '12px' },
    postContent: { color: '#555', lineHeight: '1.5', fontSize: '14px' },
    btnDetail: { background: 'none', border: 'none', color: '#2e7d32', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px', padding: 0 }
};

export default QuanLyThongBaoCuDan;
